        int low = 0;
        int high = arr.size();
        int ans=arr.size();
        while(low<=high){
            int mid = low + (high-low)/2;
            if(arr[mid]>=x){
                ans=mid;
                high=mid-1;
            }else{
                low = mid+1;
            }

        }
        if(arr[ans]==x){
            return {arr[ans],arr[ans]};
        }else if(ans==0){
            return{-1,arr[ans]};
        }else if(ans==arr.size()){
            return{arr[ans-1],-1};
        }else{
            return{arr[ans-1],arr[ans]};
        }

        return {-1,-1};
    }
};
